@startuml

class Customer {
  + address : string
  + vat_number : string
}

class Address {
  + address : string
}

class Product {
  + name : string
  + stock_level : int
}

class Order {
  + order_date : date
  + paid_date : date
  + is_fully_shipped : boolean
}

class OrderLine {
  + quantity : int
  + is_shipped : boolean
}

class Invoice {
  + invoice_date : date
}

class Shipment {
  + shipment_date : date
  + status : ShipmentStatus
}

class ShipmentLine {
  + quantity : int
}

enum ShipmentStatus {
  Packed
  Shipped
  Received
}

class Warehouse {
  + address : string
}

class DeliveryService {
  + name : string
}

Customer "1" -- "*" Address : head_office
Customer "1" -- "*" Order : places
Customer "1" -- "*" Invoice : receives
Customer "1" -- "*" Warehouse : uses
Order "1" *-- "1..*" OrderLine : contains
OrderLine "*" -- "1" Product : refers_to
Order "1" -- "0..1" Invoice : billed_by
Order "1" -- "*" Shipment : split_into
Shipment "*" -- "1,*" OrderLine : contains
Shipment "*" -- "1" ShipmentLine : consists_of
OrderLine "1" -- "*" ShipmentLine : part_of
Shipment "*" -- "0..1" DeliveryService : handled_by
Warehouse "*" -- "*" Customer : belongs_to

@enduml

